insert into public.control_versions (id, control_id, version_no, legal_reference, statement, applicability_logic, commencement_status, assessment_question, required_evidence, test_procedure, expected_result, risk_guidance, source_version_id, review_status, approved_by, approved_at, is_demo, change_note, created_by) values
  ('0000000c-0000-4000-8000-000000000001', '0000000b-0000-4000-8000-000000000001', 1, 'Section 5, Rule 3', 'Where personal data is processed on the basis of consent, the institution gives each data principal a notice that itemises the personal data and the purpose, explains how to withdraw consent and use rights, and how to complain to the Board.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Does every form or portal that collects personal data on the basis of consent show a notice with these elements at or before the request?', 'Copies of the notice as shown on each form or screen; list of collection points.', 'Sample five collection points and compare each notice with the required elements.', 'All sampled notices contain every required element.', 'High if the notice is missing at a high-volume collection point.', '0000000a-0000-4000-8000-000000000001', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000002', '0000000b-0000-4000-8000-000000000002', 1, 'Section 6', 'Consent is free, specific, informed, unconditional and unambiguous, given by a clear affirmative action, and limited to the purposes stated.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Is consent collected through an affirmative action for each stated purpose, without pre-ticked boxes or bundling with unrelated purposes?', 'Screenshots of consent screens; sample consent records.', 'Inspect consent screens and sample ten consent records.', 'No pre-ticked boxes; each purpose has its own consent.', 'High where consent underpins a high-volume activity.', '0000000a-0000-4000-8000-000000000001', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000003', '0000000b-0000-4000-8000-000000000003', 1, 'Section 9, Rules 10 and 12, Fourth Schedule', 'Before processing a child''s personal data the institution obtains verifiable consent of a parent or lawful guardian, unless a Fourth Schedule exemption applies and its conditions are met. It does not track or monitor children''s behaviour, or direct targeted advertising at children, except as the exemption allows.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'For each activity involving children, is verifiable parental consent obtained, or is a specific exemption documented with its conditions?', 'Parental consent records; documented exemption analysis per activity.', 'For each children''s-data activity, read the exemption analysis and test one consent record.', 'Every children''s-data activity has verified consent or a documented exemption.', 'Critical where children''s data is published or used for marketing.', '0000000a-0000-4000-8000-000000000002', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000004', '0000000b-0000-4000-8000-000000000004', 1, 'Section 8(5), Rule 6', 'Reasonable security safeguards are in place to prevent personal data breach, including access control, encryption or masking, logging and backups.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Are access control, encryption or masking, logging and tested backups in place for systems holding personal data?', 'Security policy; access review; backup restore test; log retention settings.', 'Review the policy and test one access review and one restore.', 'Safeguards documented and tested.', 'High for systems holding children''s or special-case data.', '0000000a-0000-4000-8000-000000000002', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000005', '0000000b-0000-4000-8000-000000000005', 1, 'Section 8(6), Rule 7', 'The institution has a documented procedure to inform the Board and each affected data principal of a personal data breach.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Is there a tested breach response procedure that names who decides, contains and notifies?', 'Breach procedure; contact list; exercise record.', 'Read the procedure and review the last exercise.', 'Procedure exists, is owned and has been exercised.', 'High: delay compounds harm.', '0000000a-0000-4000-8000-000000000002', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000006', '0000000b-0000-4000-8000-000000000006', 1, 'Section 8(7)', 'Personal data is erased when consent is withdrawn or the purpose is no longer served, unless a law requires retention, and processors are told to erase.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Is there a retention schedule and an erasure process that includes processors?', 'Retention schedule; erasure log; processor instructions.', 'Review the schedule and sample one erasure.', 'Schedule covers all activities; erasures are logged.', 'Medium to high depending on volume.', '0000000a-0000-4000-8000-000000000001', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000007', '0000000b-0000-4000-8000-000000000007', 1, 'Sections 11 to 13', 'A process exists to respond to requests for access, correction, completion, updating and erasure, and to grievances, within the prescribed time.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Can the institution log, verify and answer rights requests and grievances within the time it has set?', 'Request log; identity-check procedure; sample responses.', 'Sample five requests and trace each to its response.', 'All sampled requests answered on time after identity verification.', 'Medium to high.', '0000000a-0000-4000-8000-000000000001', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000008', '0000000b-0000-4000-8000-000000000008', 1, 'Section 8(2)', 'Personal data is processed by a processor only under a valid contract. The institution remains responsible for the processing.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Does every processor hold a written contract covering purpose limits, safeguards, breach reporting and deletion?', 'Vendor register; signed contracts.', 'Compare the vendor register with contracts on file.', 'Every processor has a contract with the required terms.', 'Critical where a processor holds children''s data without a contract.', '0000000a-0000-4000-8000-000000000001', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Demo record v1', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000020', '0000000b-0000-4000-8000-000000000001', 2, 'Section 5, Rule 3', 'Where personal data is processed on the basis of consent, the institution gives each data principal a notice that itemises the personal data and the purpose, explains how to withdraw consent and use rights, and how to complain to the Board.', 'Applies to institutions that are Data Fiduciaries.', 'Requires Verification', 'Does every form or portal that collects personal data on the basis of consent show a notice with these elements at or before the request?', 'Copies of the notice as shown on each form or screen; list of collection points.', 'Sample ten collection points and compare each notice with the required elements.', 'All sampled notices contain every required element.', 'High if the notice is missing at a high-volume collection point.', '0000000a-0000-4000-8000-000000000001', 'approved', '00000001-0000-4000-8000-000000000004', now(), true, 'Sample size raised from five to ten (demo revision)', '00000001-0000-4000-8000-000000000001'),
  ('0000000c-0000-4000-8000-000000000021', '0000000b-0000-4000-8000-000000000020', 1, 'Firm note', 'Draft firm control (visible to the firm only).', null, 'Requires Verification', 'Draft question?', null, null, null, null, '0000000a-0000-4000-8000-000000000003', 'draft', null, null, false, null, '00000001-0000-4000-8000-000000000003'),
  ('0000000c-0000-4000-8000-000000000022', '0000000b-0000-4000-8000-000000000021', 1, 'Firm note', 'Other firm''s approved control.', null, 'Requires Verification', 'Other firm question?', null, null, null, null, null, 'approved', '00000001-0000-4000-8000-000000000006', now(), true, 'Demo', '00000001-0000-4000-8000-000000000007');
