-- Link closure evidence to the action waiting for review
update public.corrective_actions set closure_evidence_id = '0000000f-0000-4000-8000-000000000005' where id = '00000010-0000-4000-8000-000000000005';

-- The security item becomes Implemented once verified evidence is linked
update public.assessment_items set result = 'implemented_verified', evidence_quality = 'verified', assessor_notes = 'Security policy verified; access review evidence also reviewed (demo).'
 where id = '0000000e-0000-4000-8000-000000000004';

-- Approve and share the school's initial assessment
update public.assessments set status = 'approved', approved_by = '00000001-0000-4000-8000-000000000004', approved_at = now() - interval '3 days',
       submitted_at = now() - interval '4 days', shared_with_client = true where id = '0000000d-0000-4000-8000-000000000001';


-- Frozen copy of the approved assessment
select a.tenant_id, a.id, a.version_no, jsonb_build_object(
  'assessment', to_jsonb(a),
  'applicability', (select coalesce(jsonb_agg(to_jsonb(d) order by d.question_code), '[]'::jsonb) from public.applicability_decisions d where d.assessment_id = a.id),
  'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.created_at, i.id), '[]'::jsonb) from public.assessment_items i where i.assessment_id = a.id)), '00000001-0000-4000-8000-000000000004'
from public.assessments a where a.id = '0000000d-0000-4000-8000-000000000001';



